// src/components/products/EditProductForm.tsx
'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { firestore } from '@/lib/firebase';
import { doc, getDoc, updateDoc, collection, getDocs, deleteDoc, addDoc } from 'firebase/firestore';

// ... (copy semua interface: Choice, CustomOption dari file AddProductForm)
interface Choice { name: string; additionalPrice?: number; }
interface CustomOption { optionName: string; type: 'radio' | 'checkbox'; choices: Choice[]; }

// Kita terima props productId
export default function EditProductForm({ productId }: { productId: string }) {
  const [product, setProduct] = useState<any>({});
  const [activeCustomOptions, setActiveCustomOptions] = useState<CustomOption[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const router = useRouter();

  // Ambil data produk dan opsi kustomnya saat komponen dimuat
  useEffect(() => {
    const fetchProduct = async () => {
      setIsLoading(true);
      // Ambil data produk utama
      const docRef = doc(firestore, 'products', productId);
      const docSnap = await getDoc(docRef);

      if (docSnap.exists()) {
        setProduct(docSnap.data());

        // Ambil data opsi kustom dari sub-collection
        const optionsCollectionRef = collection(firestore, 'products', productId, 'customOptions');
        const optionsSnapshot = await getDocs(optionsCollectionRef);
        const loadedOptions = optionsSnapshot.docs.map(doc => doc.data() as CustomOption);
        setActiveCustomOptions(loadedOptions);
      } else {
        console.log("No such document!");
      }
      setIsLoading(false);
    };

    fetchProduct();
  }, [productId]);

  // ... (copy semua fungsi handler: handleChange, handleOptionToggle, handlePriceChange dari AddProductForm)
  // Ini hanya contoh singkat, salin semua handler dari file AddProductForm.tsx
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    // ... (logika sama persis)
     const { name, value } = e.target;
     if (name === 'isAvailable') {
        setProduct((prev: any) => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
     } else {
        setProduct((prev: any) => ({ ...prev, [name]: value }));
     }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // 1. Update dokumen produk utama
      const docRef = doc(firestore, 'products', productId);
      await updateDoc(docRef, {
        ...product,
        price: Number(product.price),
      });

      // 2. Hapus semua opsi kustom lama
      const optionsCollectionRef = collection(firestore, 'products', productId, 'customOptions');
      const oldOptionsSnap = await getDocs(optionsCollectionRef);
      for (const optionDoc of oldOptionsSnap.docs) {
        await deleteDoc(optionDoc.ref);
      }

      // 3. Tambahkan kembali opsi kustom yang baru (jika ada)
      for (const option of activeCustomOptions) {
        await addDoc(optionsCollectionRef, option);
      }

      alert('Produk berhasil diperbarui!');
      router.push('/products');
    } catch (error) {
      console.error("Error updating document: ", error);
      alert('Gagal memperbarui produk.');
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) return <div>Loading form...</div>;

  // Tampilan JSX-nya SAMA PERSIS dengan AddProductForm.tsx
  // Cukup copy-paste seluruh <div className="bg-white ..."> dari AddProductForm.tsx
  return (
    <div className="bg-white p-8 rounded-2xl shadow-md">
        <h2 className="text-xl font-bold mb-6">Edit Produk: {product.name}</h2>
        <form onSubmit={handleSubmit} className="space-y-6">
            {/* ... SEMUA INPUT FORM DI SINI, SAMA SEPERTI FORM TAMBAH PRODUK ... */}
             <div><label>Nama Produk</label><input name="name" value={product.name || ''} onChange={handleChange} /></div>
             <div><label>Harga</label><input name="price" type="number" value={product.price || ''} onChange={handleChange} /></div>
             {/* ... dan seterusnya, pastikan value diisi dari state `product` */}
             <button type="submit">Update Produk</button>
        </form>
    </div>
  );
}